eval: 
$tu=explode("|",$l_i[$loc][$login]["user"]); 
if(!$char[13]) {
	if(substr($to,0,2)=="u." && isset($l_i[$loc][$to])) {
		$tus=explode("|",$l_i[$loc][$to]["user"]); 
		if ($tu[2]!=$tus[2]) {
			$tsc=explode("|",$l_i[$loc][$to]["char"]);
			if(!$tsc[13]) {
				$tt=0;
				if($tu[2]=="m" && $l_i[$loc][$speak]["f"]==$login) $tt=$l_i[$loc][$speak]["fid"];
				if($tu[2]=="f" && $l_i[$loc][$speak]["m"]==$login) $tt=$l_i[$loc][$speak]["mid"];
				if ($tt==$to) {
				if($tt) {
					$c=0;
					foreach(array_keys((array)($l_i[$loc])) as $i) if (substr($i,0,2)=="u.") $c++;
					if (legacy_cmp($c)>3) {
						if(legacy_cmp(additem($loc,$login,"","i.ring.z","count"))>0 && legacy_cmp(additem($loc,$tt,"","i.ring.z","count"))>0) {
							addjournal($loc,"all","Лайма говорит: молодожены, обменяйтесь кольцами");
							additem($loc,$login,"","i.ring.z",1);
							additem($loc,"",$login,"i.ring.z",1);
							additem($loc,$tt,"","i.ring.z",1);
							additem($loc,"",$tt,"i.ring.z",1);
							$char[13]=$tt;
							$l_i[$loc][$login]["char"]=implode("|",(array)($char));
							$tsc[13]=$login;
							$l_i[$loc][$tt]["char"]=implode("|",(array)($tsc)); 
							addjournal($loc,"all",substr($login,2)." и ".substr($tt,2).", объявляю вас мужем и женой! Жених, можете поцеловать невесту. Поздравляю!");
							additem($loc,"",$login,"i.buket",1);
							additem($loc,"",$tt,"i.buket",1);
							unset($l_i[$loc][$speak]["f"]); 
							unset($l_i[$loc][$speak]["fid"]); 
							unset($l_i[$loc][$speak]["m"]); 
							unset($l_i[$loc][$speak]["mid"]);
							}else {addjournal($loc,"all","Лайма говорит: а где же золотые кольца, молодожены? Без колец свадьба не может состояться!"); $title_v="У каждого из молодоженов должно быть по золотому кольцу";}
						}else $title_v="Недостаточно свидетелей, надо минимум два человека, кроме молодоженов";
					}else $title_v=substr($to,2)." все еще не дал(а) согласие на брак с вами.<br/><a href=\"$PHP_SELF?sid=$sid&p=$p&speak=$speak&id=svok&to=$to\">Подождать еще</a><br/><a href=\"$PHP_SELF?sid=$sid&p=$p&speak=$speak&id=svno&to=$to\">Отменить церемонию</a>";
					}else $title_v="Статус изменился, кто-то рядом с вами тоже пытается сыграть свадьбу и поэтому произошла путанница?";
				}else $title_v=substr($to,2)." уже женат(за мужем)";
			}else $title_v="Однополые браки недопустимы";
		}else $title_v=substr($to,2)." рядом нет";
	} else $title_v="Извини, <imja>, но ты уже состоишь в браке, сначала нужно развестись.";
